	arList=["🌊国产漫画🌊","🌊日本漫画🌊","🌊韩国漫画🌊","🌊欧美漫画🌊"]
	nrList=["韩国","咚漫","原创","异形","偶像","歌舞","宅斗","宅向","青春","西幻","冒险","恋爱","都市","其它","战斗","其他","灵异","科幻","纯爱","现代","总裁","推理","职场","剧情","校园","穿越","逆袭","古风","玄幻","热血","权谋","正能量","复仇","悬疑","奇幻","搞笑","日常","大女主","亲情","战争","脑洞","社会","重生","怪物","女神","多世界","异能","治愈","浪漫","魔幻"]
	arList.map((tag,index)=>{
		url=`/category/list/${index+1}<,/page/{{page}}>`;
